glass.ellipse(46, 26).center(L.x - 34, L.y - 42).fill('#ffffff').opacity(0.55);
glass.ellipse(46, 26).center(R.x - 34, R.y - 42).fill('#ffffff').opacity(0.55);

// ---- stopcock ----
var cock = draw.group();
cock.rect(292, tubeY - 13, 16, 26).fill('#d4e6ea').stroke({ color: '#8fb6c0', width: 2 }).radius(3);
var plug = cock.rect(297, tubeY - 24, 6, 48).fill('#c2dbe1').stroke({ color: '#8fb6c0', width: 2 });
