  document.getElementById('massColoringInput').checked = s.mass;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + steps.length;
  render();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

// ---- hover / click ----
[[L, 'H₂ bulb', 'Left bulb: starts full of light, fast-moving hydrogen molecules (white). Watch how quickly they spread once the stopcock opens.'],
 [R, 'O₂ bulb', 'Right bulb: starts full of heavier oxygen molecules (red, drawn larger). They diffuse too, but noticeably more slowly than H₂ — the seed of Graham\u2019s law.']]
  .forEach(function (cfg) {
