      .on('click', function () { showPopup(cfg[1], cfg[2]); });
  });
var cockHit = draw.rect(56, 60).center(300, tubeY).fill('#000').opacity(0).css('cursor', 'pointer');
cockHit.on('mousemove', function (e) { showTooltip('Stopcock', e); })
  .on('mouseleave', function () { hideTooltip(); })
  .on('click', function () { showPopup('Stopcock', 'Opening the stopcock removes the barrier — but nothing pushes the gases. Mixing happens purely through random molecular motion down the concentration gradient.'); });

render();
window.__markRendered();
