// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 600, H = 360;
draw.viewbox(0, 0, W, H);

// ---- geometry ----
var L = { x: 180, y: 160, r: 92 }, R = { x: 420, y: 160, r: 92 };
var tubeY = 160, tubeH = 16, tubeX0 = 262, tubeX1 = 338;

// deterministic pseudo-random
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
var rng = mulberry32(20240501);

function ptInBulb(b, margin) {
  var ang = rng() * Math.PI * 2;
  var rad = (b.r - margin) * Math.sqrt(rng());
  return { x: b.x + rad * Math.cos(ang), y: b.y + rad * Math.sin(ang) };
}

// fraction of a species that has crossed at time t (H2 faster than O2)
function fracH(t) { return 0.5 * (1 - Math.exp(-t / 40)); }
function fracO(t) { return 0.5 * (1 - Math.exp(-t / 120)); }

var NH2 = 36, NO2 = 28;
var particles = [];
function makeParticles(n, species, homeBulb, fracFn) {
  var fMax = fracFn(100);
  var nCross = Math.round(n / 2);
  for (var i = 0; i < n; i++) {
    var cross = i < nCross;
    var home = ptInBulb(homeBulb, 14);
    // final resting point: crossers end in the other bulb, non-crossers stay home
    var fin = cross ? ptInBulb(homeBulb === L ? R : L, 14) : ptInBulb(homeBulb, 14);
    particles.push({
      species: species,
      home: home, fin: fin,
      rank: cross ? fMax * (i + 0.5) / nCross : Infinity,
      fracFn: fracFn,
      dot: null
    });
  }
}
makeParticles(NH2, 'H2', L, fracH);
makeParticles(NO2, 'O2', R, fracO);

// ---- glassware ----
var glass = draw.group();
glass.rect(tubeX0, tubeY - tubeH / 2, tubeX1 - tubeX0, tubeH)
  .fill('#e6f2f4').stroke({ color: '#9fc3cc', width: 3 });
glass.circle(L.r * 2).center(L.x, L.y).fill('#e6f2f4').stroke({ color: '#9fc3cc', width: 3 });
glass.circle(R.r * 2).center(R.x, R.y).fill('#e6f2f4').stroke({ color: '#9fc3cc', width: 3 });
// subtle glass highlight
glass.ellipse(46, 26).center(L.x - 34, L.y - 42).fill('#ffffff').opacity(0.55);
glass.ellipse(46, 26).center(R.x - 34, R.y - 42).fill('#ffffff').opacity(0.55);

// ---- stopcock ----
