cock.rect(292, tubeY - 13, 16, 26).fill('#d4e6ea').stroke({ color: '#8fb6c0', width: 2 }).radius(3);
var plug = cock.rect(297, tubeY - 24, 6, 48).fill('#c2dbe1').stroke({ color: '#8fb6c0', width: 2 });
var handle = cock.rect(282, tubeY - 30, 36, 8).fill('#c2dbe1').stroke({ color: '#8fb6c0', width: 2 }).radius(4);
var blocker = cock.rect(294, tubeY - tubeH / 2, 12, tubeH).fill('#8fb6c0');

// ---- labels ----
var lblH2 = draw.text('H₂').font({ size: 20, family: 'sans-serif' }).center(L.x, L.y - L.r - 18).fill('#222');
var lblO2 = draw.text('O₂').font({ size: 20, family: 'sans-serif' }).center(R.x, R.y - R.r - 18).fill('#c0281c');

// ---- particles ----
var dotLayer = draw.group();
particles.forEach(function (p) {
  var r = (p.species === 'H2') ? 4 : 5.5;
  p.dot = dotLayer.circle(r * 2).stroke('none');
});

// ---- caption ----
var caption = draw.text('').font({ size: 16, family: 'sans-serif' }).center(W / 2, 300).fill('#222');
var captionSub = draw.text('').font({ size: 14, family: 'sans-serif' }).center(W / 2, 324).fill('#222');

// ---- mass legend (hidden by default) ----
var legend = draw.group().hide();
legend.rect(196, 338, 208, 18).fill('#ffffff').opacity(0.85).stroke({ color: '#ccc', width: 1 }).radius(3);
legend.circle(9).center(212, 347).fill('#8fdbe8');
legend.text('light (H₂)').font({ size: 11, family: 'sans-serif' }).move(222, 340).fill('#333');
legend.circle(11).center(310, 347).fill('#6e1423');
legend.text('heavy (O₂)').font({ size: 11, family: 'sans-serif' }).move(322, 340).fill('#333');

// ---- state ----
var curT = 0, massMode = false;

function smooth(s) { s = Math.max(0, Math.min(1, s)); return s * s * (3 - 2 * s); }

function render() {
  var t = curT;
  particles.forEach(function (p) {
    var f = p.fracFn(t);
    var prog = (p.rank === Infinity) ? 0 : smooth((f - p.rank) / 0.12);
    var x = p.home.x + (p.fin.x - p.home.x) * prog;
    var y = p.home.y + (p.fin.y - p.home.y) * prog;
    p.dot.center(x, y);
    if (massMode) {
      p.dot.fill(p.species === 'H2' ? '#8fdbe8' : '#6e1423');
    } else {
      p.dot.fill(p.species === 'H2' ? '#ffffff' : '#d42a1e');
    }
  });
  // stopcock: closed only at t == 0
  var open = t > 0;
  plug.rotate(open ? 90 : 0, 300, tubeY);
  handle.rotate(open ? 90 : 0, 300, tubeY);
  blocker.opacity(open ? 0 : 1);
  // species labels fade once mixing begins
  lblH2.opacity(open ? 0 : 1);
  lblO2.opacity(open ? 0 : 1);
  // caption
  if (t === 0) { caption.text('Stopcock closed'); captionSub.text('(a)'); }
  else if (t < 70) { caption.text('Stopcock open'); captionSub.text('(b)'); }
  else { caption.text('Some time after'); captionSub.text('stopcock open (c)'); }
  legend.opacity(massMode ? 1 : 0);
  if (massMode) legend.show(); else legend.hide();
}

// ---- interactions ----
function update_elapsedTime(v) {
  curT = v;
  render();
}
