  var slider = document.getElementById('elapsedTimeInput');
  if (curT >= 100) { curT = 0; slider.value = 0; document.getElementById('elapsedTimeVal').value = 0; }
  document.getElementById('playBtn').textContent = '⏸ Pause';
  animTimer = setInterval(function () {
    curT = Math.min(100, curT + 1);
    slider.value = curT;
    document.getElementById('elapsedTimeVal').value = curT;
    render();
    if (curT >= 100) { clearInterval(animTimer); animTimer = null; document.getElementById('playBtn').textContent = '▶ Play diffusion'; }
  }, 70);
}

// ---- demo steps ----
var steps = [
  { title: 'Stopcock closed', narration: 'With the stopcock closed, all white H₂ molecules are trapped in the left bulb and all red O₂ molecules fill the right bulb — two pure gases, no exchange possible.', t: 0, mass: false },
  { title: 'Stopcock just opened', narration: 'Shortly after opening, some H₂ has already spread into the right bulb while only a few heavier O₂ molecules have crossed left — the lighter gas diffuses noticeably faster.', t: 45, mass: false },
  { title: 'Compare by mass', narration: 'Switch to color-by-mass coding at this intermediate moment: the imbalance becomes unmistakable — the light-mass population has penetrated much farther than the heavy-mass one.', t: 45, mass: true },
  { title: 'Equilibrium', narration: 'Given enough time, random motion erases the concentration gradient entirely: both gases are distributed uniformly across both bulbs, and net movement stops even though molecules never stop moving.', t: 100, mass: false }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  if (animTimer) trigger_diffusionAnimation();
  curT = s.t;
  document.getElementById('elapsedTimeInput').value = s.t;
  document.getElementById('elapsedTimeVal').value = s.t;
  massMode = s.mass;
  document.getElementById('massColoringInput').checked = s.mass;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + steps.length;
  render();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

