}
var animTimer = null;
function trigger_diffusionAnimation() {
  if (animTimer) { clearInterval(animTimer); animTimer = null; document.getElementById('playBtn').textContent = '▶ Play diffusion'; return; }
  var slider = document.getElementById('elapsedTimeInput');
  if (curT >= 100) { curT = 0; slider.value = 0; document.getElementById('elapsedTimeVal').value = 0; }
  document.getElementById('playBtn').textContent = '⏸ Pause';
  animTimer = setInterval(function () {
    curT = Math.min(100, curT + 1);
    slider.value = curT;
    document.getElementById('elapsedTimeVal').value = curT;
    render();
    if (curT >= 100) { clearInterval(animTimer); animTimer = null; document.getElementById('playBtn').textContent = '▶ Play diffusion'; }
  }, 70);
}

// ---- demo steps ----
var steps = [
