// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 600, H = 380;
draw.viewbox(0, 0, W, H);

// ---- geometry ----
var L = { x: 168, y: 158, r: 84 }, R = { x: 432, y: 158, r: 84 };
var tubeY = 158, tubeHalf = 9;          // tube spans y 149..167
var tubeX0 = 244, tubeX1 = 356;         // overlaps both bulb rims slightly
var GLASS_FILL = '#e4f0f3', GLASS_STROKE = '#9cc0ca';

// deterministic pseudo-random
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
var rng = mulberry32(20240501);

function ptInBulb(b, margin) {
  var ang = rng() * Math.PI * 2;
  var rad = (b.r - margin) * Math.sqrt(rng());
  return { x: b.x + rad * Math.cos(ang), y: b.y + rad * Math.sin(ang) };
}

// fraction of a species that has crossed at time t (H2 faster than O2).
// Both reach ~50% at t=100 so the equilibrium picture is truly uniform.
function fracH(t) { return 0.5 * (1 - Math.exp(-t / 18)); }
function fracO(t) { return 0.5 * (1 - Math.exp(-t / 30)); }

var NH2 = 34, NO2 = 28;
var particles = [];
function makeParticles(n, species, homeBulb, fracFn) {
  var fMax = fracFn(100);
  var nCross = Math.round(n / 2);
  for (var i = 0; i < n; i++) {
    var cross = i < nCross;
    var home = ptInBulb(homeBulb, 16);
    var fin = cross ? ptInBulb(homeBulb === L ? R : L, 16) : ptInBulb(homeBulb, 16);
    particles.push({
      species: species,
      home: home, fin: fin,
      rank: cross ? fMax * (i + 0.5) / nCross : Infinity,
      fracFn: fracFn,
      dot: null
    });
  }
}
makeParticles(NH2, 'H2', L, fracH);
makeParticles(NO2, 'O2', R, fracO);

// ---- glassware (bulbs first, then tube cover so rims open smoothly) ----
var glass = draw.group();
glass.circle(L.r * 2).center(L.x, L.y).fill(GLASS_FILL).stroke({ color: GLASS_STROKE, width: 3 });
glass.circle(R.r * 2).center(R.x, R.y).fill(GLASS_FILL).stroke({ color: GLASS_STROKE, width: 3 });
// tube body covers the bulb rims at the junctions -> smooth open necks
// SVG.js: rect(width, height) then .move(x, y)
glass.rect(tubeX1 - tubeX0, tubeHalf * 2).move(tubeX0, tubeY - tubeHalf).fill(GLASS_FILL);
// gentle flare polygons at each neck for a curved transition
glass.polygon([tubeX0 - 8, tubeY - 15, tubeX0 + 14, tubeY - tubeHalf, tubeX0 + 14, tubeY + tubeHalf, tubeX0 - 8, tubeY + 15].join(' ')).fill(GLASS_FILL);
glass.polygon([tubeX1 + 8, tubeY - 15, tubeX1 - 14, tubeY - tubeHalf, tubeX1 - 14, tubeY + tubeHalf, tubeX1 + 8, tubeY + 15].join(' ')).fill(GLASS_FILL);
// tube edges with slight curve into the flares
glass.path('M ' + (tubeX0 - 6) + ' ' + (tubeY - 14) + ' Q ' + (tubeX0 + 4) + ' ' + (tubeY - 12) + ' ' + (tubeX0 + 10) + ' ' + (tubeY - tubeHalf) + ' L ' + (tubeX1 - 10) + ' ' + (tubeY - tubeHalf) + ' Q ' + (tubeX1 - 4) + ' ' + (tubeY - 12) + ' ' + (tubeX1 + 6) + ' ' + (tubeY - 14))
  .fill('none').stroke({ color: GLASS_STROKE, width: 2.5 });
glass.path('M ' + (tubeX0 - 6) + ' ' + (tubeY + 14) + ' Q ' + (tubeX0 + 4) + ' ' + (tubeY + 12) + ' ' + (tubeX0 + 10) + ' ' + (tubeY + tubeHalf) + ' L ' + (tubeX1 - 10) + ' ' + (tubeY + tubeHalf) + ' Q ' + (tubeX1 - 4) + ' ' + (tubeY + 12) + ' ' + (tubeX1 + 6) + ' ' + (tubeY + 14))
  .fill('none').stroke({ color: GLASS_STROKE, width: 2.5 });
// subtle glass highlights
glass.ellipse(44, 24).center(L.x - 32, L.y - 40).fill('#ffffff').opacity(0.5);
glass.ellipse(44, 24).center(R.x - 32, R.y - 40).fill('#ffffff').opacity(0.5);

// ---- stopcock: circular key handle on top, tapered plug through the tube ----
var CX = 300;
var cock = draw.group();
// barrel around the tube
cock.rect(24, 24).move(CX - 12, tubeY - 12).fill('#d8eaee').stroke({ color: '#8fb6c0', width: 1.5 }).radius(4);
// tapered plug (wide top, narrow bottom) — vertical = closed, rotated = open
var plug = cock.polygon([CX - 6, tubeY - 11, CX + 6, tubeY - 11, CX + 3, tubeY + 11, CX - 3, tubeY + 11].join(' '))
  .fill('#a9ccd6').stroke({ color: '#8fb6c0', width: 1 });
// stem + circular key handle above the tube
cock.rect(4, 19).move(CX - 2, tubeY - 30).fill('#c2dbe1').stroke({ color: '#8fb6c0', width: 1 });
var handleGrp = cock.group();
handleGrp.circle(18).center(CX, tubeY - 36).fill('#eaf4f6').stroke({ color: '#8fb6c0', width: 2 });
var handleBar = handleGrp.line(CX - 7, tubeY - 36, CX + 7, tubeY - 36).stroke({ color: '#8fb6c0', width: 2 });
handleGrp.circle(5).center(CX, tubeY - 36).fill('#c2dbe1').stroke({ color: '#8fb6c0', width: 1 });

// ---- species labels above the bulbs ----
var lblH2 = draw.text('H₂').font({ size: 20, family: 'sans-serif' }).center(L.x, L.y - L.r - 16).fill('#222');
var lblO2 = draw.text('O₂').font({ size: 20, family: 'sans-serif' }).center(R.x, R.y - R.r - 16).fill('#222');

// ---- particles: same size in the default view (mass difference only in mass mode) ----
var dotLayer = draw.group();
particles.forEach(function (p) {
  p.dot = dotLayer.circle(9); // r = 4.5 for both species
});

// ---- caption ----
var caption = draw.text('').font({ size: 16, family: 'sans-serif' }).center(W / 2, 306).fill('#222');
var captionSub = draw.text('').font({ size: 14, family: 'sans-serif' }).center(W / 2, 330).fill('#222');

// ---- mass legend (hidden by default): small strip near the bottom ----
var legend = draw.group();
legend.rect(200, 20).move(200, 350).fill('#ffffff').opacity(0.85).stroke({ color: '#ccc', width: 1 }).radius(3);
legend.circle(9).center(214, 360).fill('#8fdbe8');
legend.text('light (H₂)').font({ size: 11, family: 'sans-serif' }).move(224, 353).fill('#333');
legend.circle(11).center(306, 360).fill('#6e1423');
legend.text('heavy (O₂)').font({ size: 11, family: 'sans-serif' }).move(318, 353).fill('#333');
legend.hide();

// ---- state ----
var curT = 0, massMode = false;

function smooth(s) { s = Math.max(0, Math.min(1, s)); return s * s * (3 - 2 * s); }

function render() {
  var t = curT;
  particles.forEach(function (p) {
    var f = p.fracFn(t);
    var prog = (p.rank === Infinity) ? 0 : smooth((f - p.rank) / 0.12);
    var x = p.home.x + (p.fin.x - p.home.x) * prog;
    var y = p.home.y + (p.fin.y - p.home.y) * prog;
    p.dot.center(x, y);
    if (massMode) {
      // size + color encode mass only in this mode
      if (p.species === 'H2') { p.dot.size(8).fill('#8fdbe8').stroke('none'); }
      else { p.dot.size(11).fill('#6e1423').stroke('none'); }
    } else {
      p.dot.size(9);
      if (p.species === 'H2') p.dot.fill('#ffffff').stroke({ color: '#c3d4d8', width: 1 }); // outline keeps white dots legible
      else p.dot.fill('#d42a1e').stroke('none');
    }
  });
  // stopcock: closed only at t == 0 (plug vertical = blocking; rotated 90° = open bore)
  var open = t > 0;
  plug.transform({ rotate: open ? 90 : 0, cx: CX, cy: tubeY });
  handleBar.transform({ rotate: open ? 90 : 0, cx: CX, cy: tubeY - 36 });
  // species labels fade once mixing begins
  lblH2.opacity(open ? 0 : 1);
  lblO2.opacity(open ? 0 : 1);
  // caption
  if (t === 0) { caption.text('Stopcock closed'); captionSub.text('(a)'); }
  else if (t < 70) { caption.text('Stopcock open'); captionSub.text('(b)'); }
  else { caption.text('Some time after'); captionSub.text('stopcock open (c)'); }
  // legend
  if (massMode) legend.show(); else legend.hide();
}

// ---- interactions ----
function update_elapsedTime(v) {
  curT = v;
  render();
}
function toggle_massColoring(on) {
  massMode = on;
  render();
}
var animTimer = null;
function trigger_diffusionAnimation() {
  if (animTimer) { clearInterval(animTimer); animTimer = null; document.getElementById('playBtn').textContent = '▶ Play diffusion'; return; }
  var slider = document.getElementById('elapsedTimeInput');
  if (curT >= 100) { curT = 0; slider.value = 0; document.getElementById('elapsedTimeVal').value = 0; }
  document.getElementById('playBtn').textContent = '⏸ Pause';
